    private function entityKinds(int$spaceId):array{$result=[];foreach($this->all('SELECT e.id,e.kind FROM entities e JOIN network_nodes n ON n.id=e.id WHERE n.address_space_id=? ORDER BY e.id',[$spaceId])as$row)$result[(int)$row['id']]=$row['kind'];return$result;}
