    private function findReferences(array$changes):array{$refs=[];if(!$changes)return[];$sources=[];foreach($this->all("SELECT 'Dienst' kind,id,name,url||' '||description||' '||notes text FROM services UNION ALL SELECT 'Host',id,name,description||' '||notes FROM hosts UNION ALL SELECT 'Netz',id,name,description FROM network_nodes")as$row)$sources[]=$row;foreach($changes as$c)foreach($sources as$s)if(preg_match('/(?<!\d)'.preg_quote($c['old'],'/').'(?!\d)/',(string)$s['text']))$refs[]=['ip'=>$c['old'],'kind'=>$s['kind'],'id'=>(int)$s['id'],'name'=>$s['name']];return$refs;}
